import { Agent } from "@mastra/core/agent";
import { memory } from "../memory";
import { wrapMastra } from "neatlogs/mastra";
import { NEATLOGS_INSTRUCTIONS } from "../prompts";
import { getNeatlogsTools } from "../tools/neatlogs";

/**
 * Chatted with directly in the web app, and delegated to by the Primary Bot. Reads every agent's
 * Neatlogs traces and can change triage items and detections; each such call suspends for the
 * user's approval in whichever chat started it (see neatlogsToolNeedsApproval).
 */
export const neatlogsAgent = wrapMastra(new Agent({
  id: "neatlogs",
  name: "Neat Bot",
  description:
    "Analyzes the Neatlogs traces of this project's agent runs: errors, latency, token usage, evaluations, detections, and triage items. Can update triage items and create detections; every change is shown with its exact arguments and runs only after you approve it.",
  instructions: NEATLOGS_INSTRUCTIONS,
  model: "deepseek/deepseek-flash",
  memory,
  // Resolved per request so a missing key or Neatlogs outage never blocks server startup.
  tools: () => getNeatlogsTools(),
  defaultOptions: { maxSteps: 12 },
}));
import { MCPClient, type RequireToolApprovalContext } from "@mastra/mcp";

/**
 * Neatlogs' MCP tools carry no annotations (no readOnlyHint), so approval is decided by name:
 * only these known read tools skip approval. Every other tool (triage/detection writes, and any
 * tool the server adds later) needs human approval. Deny by default.
 */
export const NEATLOGS_READ_TOOLS: ReadonlySet<string> = new Set([
  "ping",
  "whoami",
  "search_traces",
  "get_trace_context",
  "get_trace_evaluations",
  "get_project_analytics",
  "list_detections",
  "get_detection_trend",
  "list_detection_groups",
  "get_detection_capabilities",
  "get_detection_status",
  "triage_list",
  "triage_get",
  "triage_get_investigation",
  "triage_list_steps",
  "triage_list_versions",
  "triage_get_version",
]);

/** Never exposed to the agent: it ingests traces rather than reading or triaging them. */
const NEATLOGS_EXCLUDED_TOOLS: ReadonlySet<string> = new Set(["log_trace"]);

export function neatlogsToolNeedsApproval({ toolName }: Pick<RequireToolApprovalContext, "toolName">): boolean {
  return !NEATLOGS_READ_TOOLS.has(toolName);
}

// Neatlogs' hosted MCP server, authenticated with the same project key the tracing SDK uses.
export const neatlogsMcp = new MCPClient({
  id: "neatlogs",
  servers: {
    neatlogs: {
      url: new URL("https://ingest.neatlogs.com/mcp"),
      requestInit: {
        headers: { Authorization: `Bearer ${process.env.NEATLOGS_API_KEY}` },
      },
      // Refuse to follow redirects/requests to any other host with the key attached.
      allowedHosts: ["ingest.neatlogs.com"],
      requireToolApproval: neatlogsToolNeedsApproval,
    },
  },
});

type NeatlogsTools = Awaited<ReturnType<typeof neatlogsMcp.listTools>>;
let cached: NeatlogsTools | undefined;

const TOOL_KEY_PREFIX = "neatlogs_"; // listTools() namespaces tools as `<server>_<tool>`.

function toolName(key: string): string | undefined {
  return key.startsWith(TOOL_KEY_PREFIX) ? key.slice(TOOL_KEY_PREFIX.length) : undefined;
}

/**
 * Resolves the Neatlogs MCP tools lazily (the agent calls this per request), minus excluded ones.
 * Degrades to no tools (logging a warning) when NEATLOGS_API_KEY is missing or the connection
 * fails, so the server still boots. Only a successful, non-empty fetch is cached.
 */
export async function getNeatlogsTools(): Promise<NeatlogsTools> {
  if (cached) return cached;
  if (!process.env.NEATLOGS_API_KEY) {
    console.warn("[neatlogs] NEATLOGS_API_KEY is not set; the Neatlogs agent has no tools");
    return {};
  }
  try {
    // listTools() reports a failed server as an empty result instead of throwing; don't cache that.
    const all = await neatlogsMcp.listTools();
    const tools = Object.fromEntries(
      Object.entries(all).filter(([key]) => {
        const name = toolName(key);
        return name !== undefined && !NEATLOGS_EXCLUDED_TOOLS.has(name);
      }),
    ) as NeatlogsTools;
    if (Object.keys(tools).length > 0) cached = tools;
    return tools;
  } catch (error) {
    console.warn("[neatlogs] could not load Neatlogs MCP tools:", error instanceof Error ? error.message : error);
    return {};
  }
}
import type { RequestContext } from "@mastra/core/request-context";
import { createTool } from "@mastra/core/tools";
import { MCPClient, type RequireToolApprovalContext } from "@mastra/mcp";
import { z } from "zod";
import { CFO_MCP_URL, cfoConfigError, getCfoAccessToken, getCfoStatus } from "../../cfo/oauth";
import { WORKSPACE_USER_KEY } from "../workspace";

/** Where a signed-in user links their cfo.ai account (relative, served by src/cfo/routes.ts). */
export const CFO_CONNECT_PATH = "/api/cfo/connect";

/**
 * Deny by default: cfo.ai annotates every tool with an explicit readOnlyHint (the inspect_* tools,
 * list_orgs and validate_code_blocks are true; every edit_*, call_connected_api and notify_user is
 * false; the risky ones are excluded entirely, see CFO_EXCLUDED_TOOLS). Only `readOnlyHint: true` skips approval; any other tool, or one without annotations,
 * needs the user's approval.
 */
export function cfoToolNeedsApproval({ annotations }: Pick<RequireToolApprovalContext, "annotations">): boolean {
  return annotations?.readOnlyHint !== true;
}

/**
 * Never exposed to the agent, even behind approval: they reach outside cfo.ai (email/Slack,
 * third-party APIs) or change account-level settings (team, org, integrations, triggers).
 */
const CFO_EXCLUDED_TOOLS: ReadonlySet<string> = new Set([
  "notify_user",
  "call_connected_api",
  "edit_team",
  "edit_org",
  "edit_integrations",
  "edit_triggers",
]);

const CFO_TOOL_KEY_PREFIX = "cfo_"; // listTools() namespaces tools as `<server>_<tool>`.

/** Drops the excluded cfo.ai tools from a listTools() result. */
function withoutExcludedTools(tools: McpTools): McpTools {
  return Object.fromEntries(
    Object.entries(tools).filter(
      ([key]) => !(key.startsWith(CFO_TOOL_KEY_PREFIX) && CFO_EXCLUDED_TOOLS.has(key.slice(CFO_TOOL_KEY_PREFIX.length))),
    ),
  ) as McpTools;
}

/** The signed-in user's id, set only by the server (src/chat-api.ts); undefined for the CLI. */
function requestUserId(requestContext: RequestContext | undefined): string | undefined {
  const value = typeof requestContext?.get === "function" ? requestContext.get(WORKSPACE_USER_KEY) : undefined;
  return typeof value === "string" && value ? value : undefined;
}

type McpTools = Awaited<ReturnType<MCPClient["listTools"]>>;
type ClientEntry = { token: string; client: MCPClient; tools?: Promise<McpTools> };

/** One MCPClient per user, keyed by user id and rebuilt when that user's access token changes. */
const clients = new Map<string, ClientEntry>();

function dropClient(userId: string, entry: ClientEntry): void {
  if (clients.get(userId) === entry) clients.delete(userId);
  void entry.client.disconnect().catch(() => {});
}

function clientFor(userId: string, token: string): ClientEntry {
  const existing = clients.get(userId);
  if (existing?.token === token) return existing;
  if (existing) dropClient(userId, existing);
  const entry: ClientEntry = {
    token,
    client: new MCPClient({
      id: `cfo:${userId}`,
      servers: {
        cfo: {
          url: new URL(CFO_MCP_URL),
          requestInit: { headers: { Authorization: `Bearer ${token}` } },
          // Refuse to follow redirects/requests to any other host with the token attached.
          allowedHosts: ["api.cfo.ai"],
          // cfo.ai sends server instructions; keep them out of the system prompt.
          forwardInstructions: false,
          requireToolApproval: cfoToolNeedsApproval,
        },
      },
    }),
  };
  clients.set(userId, entry);
  return entry;
}

/** Reports whether cfo.ai is usable for the current user. Never returns tokens. */
export const cfoConnectionStatus = createTool({
  id: "cfo_connection_status",
  description:
    "Checks whether the current user has linked their cfo.ai account. Returns configured, connected and the path where the user can connect. Call it when cfo.ai tools are missing or the user asks about the connection.",
  inputSchema: z.object({}),
  outputSchema: z.object({
    configured: z.boolean(),
    signedIn: z.boolean(),
    connected: z.boolean(),
    connectPath: z.string(),
    note: z.string(),
  }),
  execute: async (_input, context) => {
    const configured = cfoConfigError() === null;
    const userId = requestUserId(context?.requestContext);
    const connected = configured && userId !== undefined && getCfoStatus(userId).connected;
    const note = !configured
      ? "cfo.ai is not configured on this server; an administrator must set it up."
      : !userId
        ? "No signed-in user (CLI run); cfo.ai is available only in the web app after signing in."
        : connected
          ? "Connected. cfo.ai tools are available; if they are missing, cfo.ai may be temporarily unreachable."
          : `Not connected. The user can connect at ${CFO_CONNECT_PATH}.`;
    return { configured, signedIn: userId !== undefined, connected, connectPath: CFO_CONNECT_PATH, note };
  },
});

/**
 * The CFO Bot's tools for this request: the connection status tool, plus the user's cfo.ai MCP
 * tools when they have linked an account. Degrades to the status tool alone when there is no
 * signed-in user, no connection, a failed refresh, or a cfo.ai outage. Only a non-empty tool list
 * is cached, so a later request can recover.
 */
export async function getCfoTools({ requestContext }: { requestContext?: RequestContext }): Promise<McpTools> {
  const base: McpTools = { cfo_connection_status: cfoConnectionStatus };
  const userId = requestUserId(requestContext);
  if (!userId) return base;
  const token = await getCfoAccessToken(userId);
  if (!token) {
    const stale = clients.get(userId);
    if (stale) dropClient(userId, stale);
    return base;
  }
  const entry = clientFor(userId, token);
  if (!entry.tools) {
    // listTools() reports a failed server as an empty result instead of throwing.
    const pending = entry.client.listTools();
    entry.tools = pending;
    pending.then(
      (tools) => {
        if (Object.keys(tools).length === 0 && entry.tools === pending) entry.tools = undefined;
      },
      () => {
        if (entry.tools === pending) entry.tools = undefined;
      },
    );
  }
  try {
    const tools = await entry.tools;
    if (Object.keys(tools).length === 0) console.warn("[cfo] cfo.ai returned no tools for this user");
    return { ...withoutExcludedTools(tools), ...base };
  } catch (error) {
    console.warn("[cfo] could not load cfo.ai MCP tools:", error instanceof Error ? error.message : error);
    return base;
  }
}
import { Agent } from "@mastra/core/agent";
import { memory } from "../memory";
import { wrapMastra } from "neatlogs/mastra";
import { CFO_INSTRUCTIONS } from "../prompts";
import { getCfoTools } from "../tools/cfo";

/**
 * Chatted with directly in the web app, and delegated to by the Primary Bot. Uses the signed-in
 * user's own cfo.ai connection (resolved per request from the RequestContext): read tools run
 * freely, every change suspends for the user's approval (see cfoToolNeedsApproval).
 */
export const cfoAgent = wrapMastra(new Agent({
  id: "cfo",
  name: "CFO Bot",
  description:
    "Analyzes business financials, cash flow, runway, budgets, pricing, unit economics, and hiring scenarios, using live data from the user's own cfo.ai workspace when they have connected it (pages, tables, scenarios, integrations). Reads run freely; any change in cfo.ai is shown with its exact arguments and runs only after the user approves it. Never invents figures.",
  instructions: CFO_INSTRUCTIONS,
  model: "deepseek/deepseek-flash",
  memory,
  // Resolved per request: each user gets their own cfo.ai connection, or only the status tool.
  tools: ({ requestContext }) => getCfoTools({ requestContext }),
  defaultOptions: { maxSteps: 12 },
}));
import { mkdirSync } from "node:fs";
import { join } from "node:path";
import type { RequestContext } from "@mastra/core/request-context";
import { LocalFilesystem, WORKSPACE_TOOLS, Workspace } from "@mastra/core/workspace";
import { dataDir } from "../data-dir";

/**
 * RequestContext key holding the signed-in user's id. Only the server sets it (src/chat-api.ts),
 * never from client input. Delegated sub-agents receive a copy of the caller's RequestContext, so
 * they resolve the same folder.
 */
export const WORKSPACE_USER_KEY = "nlhack.workspaceUserId";

/** Folder used when no user is in the RequestContext: the CLI (`npm start`) and `mastra dev`. */
const LOCAL_FOLDER = "local";

const SAFE_USER_ID = /^[A-Za-z0-9_-]{1,128}$/;

/**
 * The user's own folder, DATA_DIR/files/<userId>. The id must be a plain folder name; anything
 * else is refused rather than mapped onto a shared or parent folder.
 */
export function userFilesDir(userId: string): string {
  if (!SAFE_USER_ID.test(userId)) throw new Error("Refusing file workspace: user id is not a safe folder name");
  return join(dataDir(), "files", userId);
}

function folderFor(requestContext: RequestContext | undefined): string {
  const value = typeof requestContext?.get === "function" ? requestContext.get(WORKSPACE_USER_KEY) : undefined;
  if (value === undefined || value === null) return userFilesDir(LOCAL_FOLDER);
  if (typeof value !== "string") throw new Error("Refusing file workspace: user id is not a string");
  return userFilesDir(value);
}

const FS = WORKSPACE_TOOLS.FILESYSTEM;

/**
 * One private file folder per user, shared by every agent. Files persist on disk across chats and
 * restarts. Only deleting needs the user's approval; editing in place (edit_file, ast_edit) is off,
 * and no sandbox or search index is configured, so no command or index tools exist.
 */
export const workspace = new Workspace({
  id: "user-files",
  name: "User files",
  filesystem: ({ requestContext }) => {
    const basePath = folderFor(requestContext);
    mkdirSync(basePath, { recursive: true });
    return new LocalFilesystem({
      basePath,
      contained: true,
      // Replaces the default text, which would put the absolute disk path in the prompt.
      instructions:
        "This is the current user's private file workspace. Use relative paths such as \"notes/plan.md\" (the root is \".\"); absolute paths and paths outside it are refused.",
    });
  },
  tools: {
    // Off by default, so only the tools listed as enabled below are ever exposed.
    enabled: false,
    requireApproval: false,
    [FS.READ_FILE]: { enabled: true },
    [FS.WRITE_FILE]: { enabled: true },
    [FS.LIST_FILES]: { enabled: true },
    [FS.GREP]: { enabled: true },
    [FS.FILE_STAT]: { enabled: true },
    [FS.MKDIR]: { enabled: true },
    [FS.DELETE]: { enabled: true, requireApproval: true },
    [FS.EDIT_FILE]: { enabled: false },
    [FS.AST_EDIT]: { enabled: false },
  },
});
